  FT["PH-H2935"] = {"id":"PH-H2935","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3499_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tiaong Central Elementary School in the Municipality of Tiaong, Province of Quezon, to Claro M. Recto Memorial Elementary School","orig":"An Act Changing the Name of the Tiaong Central Elementary School in the Municipality of Tiaong, Province of Quezon, to Claro M. Recto Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3499","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3499_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2935-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tiaong Central Elementary School in the Municipality of Tiaong, Province of Quezon, is hereby changed to Claro M. Recto Memorial Elementary School."}},{"id":"PH-H2935-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2936"] = {"id":"PH-H2936","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3500_1962.html","fetchedAt":"2026-10-06","articleCount":34,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period From July First, Nineteen Hundred and Sixty-Two to June Thirtieth, Nineteen Hundred and Sixty-Three, and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period From July First, Nineteen Hundred and Sixty-Two to June Thirtieth, Nineteen Hundred and Sixty-Three, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3500","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 34 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3500_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2936-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of funds. —The following sums, or so much thereof as may be necessary, are appropriated out of any funds in the Philippine Treasury not otherwise appropriated for the operation of the Government of the Republic of the Philippines during the period from July first, nineteen hundred and sixty-two to June thirtieth, nineteen hundred and sixty-three, except where otherwise specifically provided:\n[Itemized portions on salaries and wages and other expenditures are omitted for lack of space] GENERAL PROVISIONS"}},{"id":"PH-H2936-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Personnel in the classified Civil Service not to be affected by the adoption of the Performance Budget. —The adoption of the budgetary system based on functions, activities and projects in terms of expected results shall neither result in any manner in the laying off of personnel in the classified Civil Service except for cause as provided by law nor in the reduction of actual salaries of incumbents or demotion in rank or change of status."}},{"id":"PH-H2936-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority to use savings in appropriations to cover deficits. —Except as otherwise provided in this Act, any savings in the regular appropriations authorized in this Act for any Executive Department for \"personal services,\" for \"maintenance and other operating expenses,\" and for \"equipment\" of the bureaus and offices under the same Department may, with the approval of the President, be used to cover a deficit in any other item of the regular appropriations except for personal services, under the same Department: PROVIDED, That whenever authorized positions are transferred from one program to another within the same Department, the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the Department concerned. In no case, however, shall any item of appropriations be augmented, pursuant to the authority granted in this section by more than thirty per centum of the original appropriation provided in this Act for such item."}},{"id":"PH-H2936-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Quarterly report to Congress on transfers of appropriations and accomplishments of bureaus and offices. —The Auditor General and the Commissioner of the Budget shall submit separately to the Congress a quarterly report of any transfer of appropriation made to cover a deficit, the report to specify the items and the amounts involved and shall furnish copies to each member of Congress in his office. The heads of bureaus or offices whose appropriations are based on the Performance Budget shall likewise submit separately to each member of Congress a quarterly report of their accomplishments."}},{"id":"PH-H2936-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Authority to use savings for other purposes. —The President of the Philippines is authorized to use any savings in the appropriations provided in this Act for the Executive Departments for the settlement of the following obligations incurred during the current fiscal year and/or previous fiscal years, the limitation in section 7-I(27) of Commonwealth Act Numbered Two hundred forty-six, as amended, notwithstanding: (1) claims under section 699 of the Revised Administrative Code, as amended, and the Workmen's Compensation Act, whichever is applicable, of officers, employees and laborers who died or were injured in line of duty; (2) commutation of the money value of the additional leave, extended leave and accrued leave earned by American and deceased Filipino officers and employees, or by Filipino officers and employees separated from the service except for cause, for service rendered prior to November twenty-ninth, nineteen hundred and thirty-six; (3) purchase of equipment to replace those that may be lost through accident, fire or other calamity, or may have been damaged through the same cause, the disposal of which is deemed reasonable and necessary, if it would be more expensive to have them repaired, and purchase, with the approval of the President, of equipment, including motor vehicles, to replace unserviceable ones condemned by the Auditor General; (4) payment of salaries of suspended employees who have subsequently been exonerated; (5) payment of the share of the National Government in the salaries of national officials in newly created cities and provinces where no appropriation has been provided therefor; (6) three per cent contribution of the Government to the Government Service Insurance System for the employee's insurance premiums corresponding to the period from December thirty-first, nineteen hundred and forty-one to February twenty-eight, nineteen hundred and forty-five, pursuant to section four of Republic Act Numbered One hundred thirty-two, the provisions of section 7(c) of Commonwealth Act Numbered One hundred eighty-six, as amended, to the contrary notwithstanding; (7) commutation of vacation and sick leave of employees who may be retired under existing laws; (8) additional compensation to government nurses assigned to public health nursing at P50 a month in lieu of quarters, subsistence and laundry allowances as provided under section three of Republic Act Numbered Six hundred forty-nine; (9) purchase or rental of accounting machines to carry out the plan of mechanizing the accounting system of the Government; (10) cash commutation of the accumulated vacation and sick leave of employees who voluntarily resign or are separated from the service thru no fault of their own, in accordance with the provisions of Republic Act Numbered Six hundred eleven, as amended by Republic Act Numbered One thousand eighty-one; (11) printing of briefs in cases appealed by the Government; (12) improvement of food rations in government hospitals and leprosaria; (13) rural improvement; (14) payment of premiums for the insurance of government properties; (15) payment of gratuities of employees who are. laid off as a result of the elimination of their positions in this Act and the government reorganization under Republic Act No. 997; as amended, at a rate equivalent to one month salary for every year of continuous satisfactory service rendered but not exceeding twelve months, on the basis of the last salary received: PROVIDED, That if said employees are entitled to gratuity or pension under any retirement law, they shall select either such gratuity or pension or the gratuity herein provided; (16) unpaid claims for commutation of maternity leave of absence under the provisions of Republic Act No. 1564; (17) opening of additional primary classes; (18) adjustment of salaries of national officials and employees resulting from the reclassification of provinces and municipalities; (19) payment of the gratuities of officers and employees who retire under the provisions of paragraph (c) of Section twelve of Commonwealth Act Numbered One hundred eighty-six, as amended, and further amended by Republic Act Numbered One thousand six hundred sixteen and Republic Act Numbered Three thousand ninety-six (20) payment of salary adjustments of officials and employees resulting from the. re-classification and/or reallocation of their positions to a higher class or salary range, and those whose positions have not been included in the salary adjustments provided in this Act; (21) payments of the difference between the salary already received by an official or employee during the preceding fiscal year and the amount appropriated for his item in this Act; (22) for aid to the Provinces of Southern Leyte and Catanduanes, P300,000 each; (23) for the implementation of the rural health program provided in Republic Act No. 1082, as amended; (24) payment of prior years obligations of any bureau or office of the National Government with the Bureau of Printing; (25) for aid to the Provinces of Surigao del Norte, Surigao del Sur, and Davao, P300,000 each; (26) for additional expenses incident to the purchase of foreign exchange; (27) covering any deficit in the Salary Adjustment Fund; (28) for aid to the municipalities of Batanes Province, P50,000; (29) for aid to the Catanduanes Provincial High School, P75,000; and (30) payment of expenses for the celebration of the anniversary of the Independence of the Philippines on June Twelfth or July Fourth, nineteen hundred sixty-two but not to exceed P80,000: PROVIDED, That the amount may be spent before July first, nineteen hundred sixty-two."}},{"id":"PH-H2936-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Suspension of expenditures of appropriations and transfers thereof. —Except as otherwise provided in this Act and whenever in his judgment the public interest so requires, the President, upon notice to the head of office concerned, is authorized to suspend or otherwise stop the expenditure of any amount herein appropriated in any item or items for the Executive Departments for any purpose, except amounts for salaries of positions with incumbents, and thereupon the funds affected by such action shall become available for any other expenditures authorized in this Act for the Executive Departments as the President may determine, except for personal services: PROVIDED, That whenever authorized positions are transferred from one program to another, the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the office concerned. In no case, however, shall any item of appropriation be augmented, pursuant to the authority granted in this section, by more than thirty per centum of the original appropriation provided in this Act for such item. The Auditor General and the Commissioner of the Budget shall report separately to the Congress within a period of thirty days any suspension or transfer of funds made by the President during the previous quarter and shall furnish copies to each member of Congress in his office."}},{"id":"PH-H2936-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Failure on the part of the Auditor General and the Commissioner of the Budget to make report. —Failure on the part of the Auditor General and the Commissioner of the Budget to make the report herein required within the period specified therein shall automatically cause the suspension of the payment of their salaries until they shall have complied therewith."}},{"id":"PH-H2936-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Provision for \"excess of actual salary. \"—Appropriations provided in this Act may be used for payment of excess of actual salaries to the incumbent of a position to which said \"excess\" pertains who is actually receiving the same \"excess\" as part of the salary granted to him upon his appointment to the said position before the reduction of the basic pay thereof to the amount provided: PROVIDED, HOWEVER, That if the position be vacated and the successor to its previous incumbent shall have previously received an equal salary plus the \"excess of actual salary\" in the same or any other branch of the government service, such excess shall be allowable to him."}},{"id":"PH-H2936-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Purchase of locally manufactured equipment, parts, accessories, supplies, and materials. —All appropriations for the purchase of equipment, supplies and materials authorized in this Act shall be available only for locally manufactured equipment, parts, accessories, supplies and materials, except when none is available in the market, or when the prices of the locally manufactured article exceed those determined by the Flag Law by ten per cent."}},{"id":"PH-H2936-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Renting of automobiles, jitneys or trucks for a continuous period exceeding fifteen days prohibited. —No appropriation provided in this Act for the Executive Departments shall be used for renting automobiles, jitneys or trucks on the monthly basis nor on the daily basis for a continuous period exceeding fifteen days."}},{"id":"PH-H2936-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Authority to purchase motor vehicles. —No appropriation authorized in this Act shall be used for the purchase of automobiles, jitneys, jeeps, station wagons, motorcycles and other motor vehicles unless otherwise specifically provided in this Act notwithstanding the authority given in Section fourteen hereof to the office concerned to use, operate and maintain government motor vehicles."}},{"id":"PH-H2936-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Officials entitled to government motor transportation. —The following officials are entitled to use government motor transportation chargeable against the appropriations authorized in this Act except where otherwise provided in this Act or other special laws:\n1. The President of the Philippines.\n2. The Vice-President of the Philippines,\n3. The President of the Senate,\n4. The Speaker of the House of Representatives,\n5. The President Pro-Tempore of the Senate,\n6. The Majority Floor Leader of the Senate,\n7. The Chairman, Committee on Finance of the Senate,\n8. The Chairman, Committee on Ways and Means of the Senate,\n9. The Chairman, Committee on Accounts of the Senate,\n10. The Chairman, Committee on Foreign Relations of the Senate,\n11. The Chairman, Committee on Public Works of the Senate,\n12. The Minority Floor Leader of the Senate,\n13. The Secretary of the Senate,\n14. The Speaker Pro-Tempore of the House of Representatives,\n15. The Majority Floor Leader and the Assistant Majority Floor Leader of the House of Representatives,\n16. The Chairman, Committee on Appropriations of the House of Representatives,\n17. The Chairman, Committee on Accounts of the House of Representatives,\n18. The Chairman, Committee on Ways and Means of the House of Representatives,\n19. The Chairman, Committee on Foreign Affairs of the House of Representatives,\n20. The Chairman, Committee on Public Works of the House of Representatives,\n21. The Chairman, Committee on Education of the House of Representatives,\n22. The Minority Floor Leader of the House of Representatives,\n23. The Secretary of the House of Representatives,\n24. The Chief Justice of the Supreme Court,\n25. The Presiding Justice of the Court of Appeals,\n26. The Undersecretary of Foreign Affairs,\n27. The Ambassadors, Ministers Plenipotentiary and Consuls in charge of consulates while in their respective stations abroad, and\n28. The Chief of Staff and the Vice-Chief of Staff and the Commanding Officers of the other Major Services of the Armed Forces of the Philippines."}},{"id":"PH-H2936-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Officials entitled to transportation allowance. —The Department Secretaries, including the Executive Secretary, the Auditor General, the Administrator of Economic Coordination, the Commissioner of the Budget, the Public Information Secretary, the Chairman, Presidential Committee on Administration Performance Efficiency, the Technical Assistant on Local Governments and Civil Affairs, the Chairman, National Economic Council, the Chairman, Commission on Elections, the Social Welfare Administrator, the Chairman, Commission on National Integration, the Chairman, National Science Development Board, the Commissioner of Civil Service, and the Chairman and the members of the Reparations Commission, are hereby granted a commutable transportation allowance of two hundred fifty pesos each per month; the Department Undersecretaries, excluding the Undersecretary of Foreign Affairs, and officials with the same rank, including the Legal Adviser to the President, the Assistant Executive Secretaries, the Deputy Commissioner of the Budget, the Deputy Auditor General, the Deputy Administrator of Economic Coordination, the Deputy Commissioner of Civil Service, the Government Corporate Counsel, the Executive Judge, Court of Agrarian Relations, the Legislative Secretary, the Head Legislative Liaison Officer, the Presiding Judge, Court of Industrial Relations, the Presiding Judge, Court of Tax Appeals, the Commissioner, Land Registration Commission, the Public Service Commissioner, the Presiding Judge, Juvenile and Domestic Relations Court, the Chairman of Land Tenure Administration, the Administrator, Philippine Veterans Administration, the Vice-Chairman and the Auditor, National Science Development Board, the Commissioner, Philippine Atomic Energy Commission, the Commissioner, National Institute of Science and Technology, the Judicial Superintendent, the Department Legal Counsel, and the Chief Prosecuting Attorney, Department of Justice the Commissioner of Immigration, the Administrator of Social Security System, the Director of Labor Standards, as ex-officio Chairman of the Labor Standards Commission, the Director of Workmen's Compensation, as ex-officio Chairman of the Workmen's Compensation Commission, the Director of Labor Relations, the Director of Coast and Geodetic Survey, as ex-officio Chairman of the Lighthouse Board and ex-officio member of the Philippine Port Commission, the Executive Director of the National Economic Council, the Tariff Commissioner, the Agricultural Tenancy Commissioner, the Tenancy Mediation Commissioner, the Cabinet Secretary, the Presidential Staff Secretary, the Presidential Protocol Officer, the Private Secretary and the Private Physician to the President, the Director of Classification and Compensation, the Chief, Budget Operations Service, the Administrator, Motor Vehicles Office, the Heads of Offices including the Chief Coordinator in the Department of Foreign Affairs, the Commissioner of Customs, the Commissioner of Internal Revenue, the Treasurer of the Philippines, the Executive Director, Joint Legislative-Executive Tax Commission, the Director of Fiber Inspection Service, the two members, Commission on Elections, and the Solicitor General, two hundred pesos each per month; and the following officials, directors or chiefs of bureaus arid offices and the Sergeant-at-Arms of the House of Representatives, one hundred pesos each per month, chargeable against the appropriation authorized in this Act for their respective Offices:\n1. The Deputy Commissioner of Internal Revenue,\n2. The Director of Lands,\n3. The Director of Public Works,\n4. The Commissioner of Public Highways,\n5. The Director of Public Schools,\n6. The Director of Health Services,\n7. The Director of Medical Services,\n8. The Director of Disease Control,\n9. The Director of Research Laboratories,\n10. The Insurance Commissioner,\n11. The Director of Prisons,\n12. The Director of Mines,\n13. The Director of Forestry,\n14. The Postmaster General,\n15. The Director of Civil Aviation,\n16. The Director of Private Schools,\n17. The First Assistant Solicitor General,\n18. The Director of Quarantine,\n19. The Director of Commerce,\n20. The Director of Weather Bureau,\n21. The Director of the Census and Statistics,\n22. The Director of Printing,\n23. The Director, National Bureau of Investigation,\n24. The Chairman, Code Commission,\n25. The Director of Plant Industry,\n26. The Director of Animal Industry,\n27. The Director of Fisheries,\n28. The Director of Soils,\n29. The Director of Agricultural Extension,\n30. The Director of Telecommunications,\n31. The Director of Public Libraries,\n32. The Director and the Assistant Director of the Philippine General Hospital,\n33. The Director of Veterans Memorial Hospital,\n34. The Irrigation Administrator,\n35. The Director, Institute of National Language,\n36. The Director of National Museum,\n37. The Administrator, Sugar Quota Administration,\n38. The Director, Philippines Patent Office,\n39. The Director of Supply Coordination,\n40. The Director of Building and Real Property Management,\n41. The Director, Records Management,\n42. The Director of National Media Production Center,\n43. The Director of Forest Products Research Institution,\n44. The Reforestation Administrator,\n45. The Civil Defense Administrator,\n46. The Director of Parks and Wildlife,\n47. The seven Presidential Staff Assistants,\n48. The Vice-Chairman and Executive Director of the Board of Technical Surveys and Maps,\n49. The two Associate Judges, Court of Tax Appeals,\n50. The Chief of the Construction and Maintenance Division, Bureau of Public Highways,\n51. The Assistant Tariff Commissioner,\n52. The Manager, UNICEF Child Feeding Programmes, and the Board Secretary II, UNICEF Administrative Committee,\n53. The Deputy Commissioner of Customs,\n54. The Collector of Customs for Manila,\n55. The Five Associate Commissioners, Public Service Commission,\n56. The Members, Land Tenure Administration,\n57. The Four Associate Judges of the Court of Industrial Relations,\n58. The Assistant Land Registration Commissioner,\n59. The Assistant Judicial Superintendent, the Head Executive Assistant and the Administrative Officer VI, Department of Justice,\n60. The two Associate Commissioners, Workmen's Compensation Commission,\n61. The two Associate Commissioners, Labor Standards Commission,\n62. The Assistant to the Secretary, the Department Legal Counsel, the Administrative Officer and the Senior Executive. Assistant (ILO Affairs Consultant), Department of Labor,\n63. The Director of Field Operations, Department of Labor,\n64. The Director, Bureau of Women and Minors,\n65. The Director of Apprenticeship,\n66. The Chiefs, Field Health Operations, Administrative Services, Health Education and Personnel Training, Disease Intelligence Center, and the Regional Health Directors and the Deputy Regional Health Director, Department of Health,\n67. The Chief, Manpower Services,\n68. The Commissioner, Securities and Exchange Commission,\n69. The Secretary of the Senate Electoral Tribunal,\n70. The Secretary, the Finance and Rate Regulation Officer, the Chief Attorney, the Chief Utilities Regulation Engineer, the Transportation Regulation Chief, and the Public Utilities Advisers of the Public Service Commission,\n71. The Chiefs, Management Service, National Accounting Service, Legislative and Fiscal Policy Staffs and Administrative Service, Budget Commission.\n72. The Deputy Commissioner, National Institute of Science and Technology, and the Deputy Commissioner, Philippine Atomic Energy Commission,\n73. The Chief Volcanologist, Commission on Volcanology,\n74. The Clerk of Court of the Supreme Court,\n75. The Clerk of Court, Court of Appeals,\n76. The Department Managers, the Chief, Administrative Department, the Executive Liaison Officer, the Legislative Liaison Officer, the Chief, Audit Methods and Training Staff and the General Counsel, General Auditing Office,\n77. The Chief, Division of Financial Management and Controls of the Department of Foreign Affairs, Ambassadors, and Ministers who may be on special detail in the Home Office,\n78. The Assistant Secretaries for Administration and Fiscal Affairs, the Head Executive Assistant, the Chief Supervising Treasurer, the Chief Finance Investigator, the Chief, Administrative Division, the Chief, Personnel Division, the Chief Tax Adviser and the Chief, Public Debt Management Division, Department of Finance,\n79. The Elections Executive Officer (Secretary),\n80. The Head of Staff (financial adviser) of the Senate,\n81. The Technical Assistant on legislative matters, the Advisor on Public Works, and the Secretary to the Senate President, Senate,\n82. The four Deputy Administrators, Philippine Veterans Administration,\n83. The Legal Adviser in the Department of Foreign Affairs,\n84. The Director of the Cooperatives Administration Office\n85. The two Associate Commissioners, the Technical Adviser on Sociological, Cultural and Educational Affairs and the Senior Industrial Research Technologist of the Commission on National Integration,\n86. The Deputy Administrator of Civil Defense,\n87. The Assistant Agricultural Tenancy Commissioner,\n88. The Administrative Officer IV, Land Registration Commission, and\n89. The Assistant Director of Civil Aviation."}},{"id":"PH-H2936-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Bureaus and offices entitled to use, operate and maintain government motor vehicles and launches. —No bureau or office shall use, operate or maintain from the appropriations authorized in this Act government service, cars, jeeps, station wagons, vans, service trucks, pickup trucks, launches, speedboats, motorcycles, etc., except the following:\n1. The House, of Representatives, for general service purposes;\n2. The Senate, for general service purposes;\n3. Malacañang, for general service purposes;\n4. The National Intelligence Coordinating Agency, in the coordination of the national intelligence activities and in carrying out its functions in the interest of national security;\n5. The Civil Defense Administration, for general service purposes in connection with the establishment and administration of the national civil defense program;\n6. The Philippine Broadcasting Service, for covering special events for delayed broadcasts, servicing of sponsored programs, contacting artists, fetching \"sign on\" personnel and conducting home those \"signing off\";\n7. The National Media Production Center, for delivery of different media of mass communications, such as press releases, handbills, pamphlets, posters, motion pictures, filmstrips, etc., and for motion picture and photo-essay coverage of different projects of the government;\n8. The UNICEF Programmes of the Philippines, for use in connection with the supervision and inspection of feeding agencies in the cities and rural areas;\n9. The Social Welfare Administration, for ministering relief, during military actions against dissidents, to evacuees, to the injured and incapacitated and to the victims of typhoons, earthquakes, fires, floods, tidal waves and volcanic eruptions, and for conducting the inmates of Welfareville to and from the courts, hospitals and other offices, procuring materials and food supplies for their subsistence, and delivering food to the various units within the Welfare-vine compound, including collection and disposal of garbage;\n10. The Budget Commission, for gathering from the various government offices and instrumentalities of such data and information as are essentially material or pertinent to the exercise of authority over budget operations and control, for the performance of duties connected with the preparation of the National Budget, and for wage and position classification survey, including surveys and studies on organization and methods analyses;\n11. The Department of Foreign Affairs, for carrying out protocol duties, including those connected with the arrival or visit in the Philippines of high dignitaries and officials or accredited representatives of foreign governments, and for general service purposes particularly in relation to the delivery of diplomatic pouches to and from points of embarkation or shipment;\n12. The Bureau of Customs, for use as the Collector of Customs may recommend and the Commissioner of Customs may approve;\n13. The Bureau of Internal Revenue, including its Regional Offices, for strict enforcement of the internal revenue laws and regulations and detection of violation thereof;\n14. The Bureau of the Treasury, for transportation of cash from the Central Bank of the Philippines to the Bureau of Treasury, and vice versa;\n15. The Office of the Insurance Commissioner, for examination of the financial condition and methods of doing business of insurance companies and for the inspection of buildings in the different blocks of Manila and its neighboring cities and municipalities and other risks in connection with the supervision of said office over the fixing of premium rates on non-life insurance, and for general service purposes;\n16. The National Bureau of Investigation, for detection and investigation of crimes and criminals and other law violations;\n17. The Bureau of Immigration, for the enforcement of immigration laws;\n18. The Court of Tax Appeals, for transportation of its personnel whenever the Court holds its hearing outside of the City of Manila pursuant to Section 6 of Republic Act No. 1125;\n19. The Court of Agrarian Relations, for transportation or its personnel whenever they go out to hear cases or take evidence in places other than their headquarters, or make settlement pursuant to the decisions of the court;\n20. The Bureau of Prisons, for conducting prisoners to and from the Bureau of Prisons, inspection of prison institutions and stations, procuring food supplies and materials, and delivering products and/or manufactures of the Prison Industries In Muntinlupa and in the penal colonies;\n21. The Juvenile and Domestic Relations Court, for conducting to and from the court, dependent or neglected children or juvenile delinquents committed to the care of persons or institutions and for inspection and supervision thereof;\n22. The Office of the Secretary of Agriculture and Natural Resources, for gathering agricultural statistics for researches and analyses in agriculture, for distribution of agricultural information materials for guidance of farmers in improving their farming methods, and for conducting inspection trips to coordinate agricultural programs;\n23. The Agricultural Tenancy Commission and the Tenancy Mediation Commission, for the administration and implementation of Republic Act No. 1199 particularly mediation and legal aid activities, distribution of information materials, conducting rallies, researches, and farm management investigations in the different regions of the country;\n24. The Bureau of Plant Industry, for the control of abaca mosaic and other plant pests and diseases, and for supervision of agricultural experiment stations, and seed farms and other plants production activities;\n25. The Bureau of Animal Industry, for the distribution of animal products and transportation of animals and feeds, including insemination works;\n26. The Bureau of Forestry, for forest management and land uses, domain use classification, research, prevention of forest destruction, scaling and lumber grading, and general administration, including transportation of cinchona barks, equipment, and supplies and materials;\n27. The Bureau of Lands, for the survey and subdivision of public agricultural lands and land management, for general administration and supervision, including the transportation and delivery of patents and important documents to and from the Office of the Secretary and other government offices, attendance at official conferences, seminars and meetings, and for transportation of equipment, supplies and materials ;\n28. The Bureau of Mines, for the transportation of mineral samples to and from the office for the geological, mineralogical and mineral land survey parties operating in the different parts of the Philippines;\n29. The Bureau of Fisheries, for the collection of marine specimens, inspection of experimental fish farms, distribution of seedlings, fisheries surveys and fish plantings, attendance at fisheries seminars, conferences and meetings, transportation of furniture, equipment and supplies, for provincial stations and fish farms, and enforcement of fishery laws, rules and regulations;\n30. The Bureau of Soils, for carrying out soil survey and conservation work in the different regions of the country;\n31. The Bureau of Agricultural Extension, for carrying out its extension work and diffusing among the people, particularly those in rural areas, useful and practical information on agriculture, soil conservation, livestock, fisheries, forest conservation, public lands and natural resources laws, home economics and rural life by means of field demonstrations, lectures, conferences, publications and other means of disseminating information;\n32. The Parks and Wildlife Office, for the. supervision of parks and recreational centers and enforcement of regulations to conserve wildlife, game, fish, etc.;\n33. The Bureau of Fiber Inspection Service, for carrying out its work of inspection and supervision of fiber grading-baling establishments, fiber improvement and demonstration work;\n34. The Department of Public Works and Communications, for gathering from its bureaus, offices and agencies, including those of other government offices and instrumentalities, of such data and information as are essentially material or pertinent to the formulation of long range public works programs and in evaluating and checking of accomplishments and expenditures against duly approved programs of work;\n35. The Bureau of Public Works, for undertaking the construction of public works projects, inspection and supervision thereof, and for the procurement of construction supplies and materials;\n36. The Bureau of Public Highways, for carrying out its functions of construction and maintenance of roads and bridges and those activities connected therewith, inspection and supervision of highway and bridge construction and maintenance projects, and for the procurement of construction supplies and materials;\n37. The Bureau of Posts, for the operation of the postal service;\n38. The Bureau of Telecommunications, for the construction, repair, transfer and maintenance of telegraph, telephone, and radio stations and circuits and the delivery of telegrams and radiograms;\n39. The Motor Vehicles Office, for the enforcement of the provisions of the Motor Vehicle Law and for general service purposes;\n40. The Office of the Secretary of Education, for the inspection of public and private schools, public libraries, investigation of cases which require immediate attention, and performance of its supervisory functions;\n41. Trade and industrial, agricultural, rural and farm schools and other vocational schools, for instructional purposes requiring the use, demonstration and/or operation of motor or other powered vehicles and for transporting and marketing their finished products for public consumption;\n42. The Bureau of Private Schools, for the inspection of private schools that are in out-of-the-way places, and for undertaking rush investigation of complaints from various sources;\n43. The Department of Labor, for the use of field personnel in the enforcement of labor laws throughout the Philippines and for the use of its headquarters entities in making field inspections, special investigations and economic surveys necessary for the administration of labor laws;\n44. The Bureau of Coast and Geodetic Survey, for carrying out field reconnaissance, triangulations, precise leveling and magnetic and gravity measurements, ship servicing canvass, procurement and delivery of supplies, and delivery or receipt of official publications, documents and shipments;\n45. The Armed Forces of the Philippines, when on military operations or on active duty in the restoration and maintenance of peace and order;\n46. The Department of Health, for the use of the Tuberculosis Control Project in BCG Vaccination and Traveling X-ray Examination Units, the Office of Health Education and Personnel Training in exhibiting health films and dissemination of health information in rural areas, the Bureau of Research and Laboratories in connection with health research including the distribution of vaccines, sera and other biological preparations, the Office of Administrative Services for the procurement of medicines, medical and office supplies, and other materials, their storage, and their distribution and shipment to the field to serve the rural areas;\n47. The Bureau of Medical Services and government hospitals, for ambulance service and procuring food supplies and materials for the subsistence of patients and personnel entitled thereto;\n48. The Bureau of Health Services, for health, sanitation and prevention and control of epidemics;\n49. The Bureau of Quarantine, whenever used by quarantine officers exclusively for quarantine work;\n50. The Philippine General Hospital, for ambulance and domiciliary services and procuring food, supplies and materials for the subsistence of patients and personnel entitled thereto;\n51. The Office of the Secretary of Commerce and Industry, for the promotion of retail trade;\n52. The Civil Aeronautics Administration, for the operation and maintenance of its landing fields including supervision and reconstruction or repair of signaling equipment located thereat;\n53. The Bureau of the Census and Statistics, for carrying out various census activities and/or operations;\n54. The Weather Bureau, for the maintenance, operation and inspection of its meteorological stations, including the Manila International Airport Forecasting Center and the Diliman Geophysical and Astronomical Stations, and delivery of supplies thereto;\n55. The Office of Economic Coordination, for use in inspecting projects being undertaken by government corporations, including private industrial establishments applying for tax exemption under Republic Act Numbered Thirty-five, and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of the said corporations;\n56. The National Institute of Science and Technology, for visit and inspection of factories, for the collection of forest plant, animal and marine by-products and agricultural wastes for use in research and laboratory investigations, including survey of sources of raw materials in different regions and other activities and for general service purposes;\n57. The General Auditing Office, for the inspection of the delivery of equipment and supplies and materials to the various bureaus and offices of the Government, as well as to sites of public works construction, and for surprise examinations of disbursing officers;\n58. The Commission on Volcanology, for inspecting and observing volcanoes and warning people in danger areas;\n59. The National Economic Council, including the Office of the Chairman, Office of National Planning, Office of Foreign Aid Coordination, and Office of Statistical Coordination and Standards, for use in the follow up and execution of certain phases of the national program of economic and social development and the gathering of data and information for studies and research work being undertaken for the formulation of economic policies, including tariff structure and international commercial relations; for use in inspecting projects being undertaken by the Government jointly with the International Cooperation Administration and in gathering and transmitting data necessary for the efficient supervision and coordination of the activities of projects; for use in conducting surveys of statistical services of the Government with a view to reviewing, appraising and allotting activities among the statistical agencies; and for use by the ranking officials of the National Economic Council in attending conferences and for gathering and compiling of data for the preparation of the agenda of the council meetings and the distribution of notices of meetings of the different council members;\n60. The Bureau of Printing, for the delivery and/or shipment of printed matters, books and/or forms to various offices;\n61. The Forest Products Research Institute, for the transportation of logs, timber, lumber and other forest products as materials for research as well as supplies, materials, machinery, equipment and personnel necessary for research;\n62. The National Science Development Board, for use in inspecting research projects undertaken by government offices, bureaus, and entities and private establishments to coordinate all scientific and technological researches;\n63. The Philippine Atomic Energy Commission, for use in the coordination and execution of nuclear research plans, attendance of staff members in conferences and consultations with different public officers and representatives of foreign governments, and the setting up of a training program in cooperation with the U. P.;\n64. The Bureau of Building and Real Property Management, for the performance and coordination of program related to the maintenance, repair and custody of national buildings and the administration of real property of the National Government;\n65. The Office of the Secretary of General Services, for regulating and performing for Government entities, the functions pertaining to procurement and supply, maintenance and custody of real property, disposal of surplus property, promotion of sound records management, printing and media production services;\n66. The Civil Service Commission, for general service purposes;\n67. The Boards of Examiners, for carrying out their functions, including the holding of examinations for the practice of different professions regulated by the Government;\n68. The Office of the Secretary of Finance, for transporting its personnel in connection with the examination and/or investigation of factories or establishments of grantees of, or applicants for, tax-exempting privileges as new and necessary industries; for attending conferences at which the Department of Finance is represented; and for other official purposes;\n69. The Office of the Secretary of National Defense, in supervising the national defense program and in the campaign for and maintenance of peace and order;\n70. The Bureau of Disease Control, for sanitaria ambulance service and procuring food supplies and materials for lepers, malaria control work, Traveling Skin Clinics and Social Hygiene Services;\n71. The Land Tenure Administration, for carrying out its functions and activities provided in Republic Act No. 1400, as amended, and other Acts entrusted to it for implementation;\n72. The Commission on National Integration, for general service purposes and for carrying out the provisions of Republic Act No. 1888;\n73. The Reparations Commission, for carrying out its functions and activities under Republic Act No. 1789, as amended;\n74. The Joint Legislative-Executive Tax Commission, for carrying out its functions and activities under Republic Act No. 2211;\n75. The Reforestation Administration, for plantation management and general administration, including the transportation of equipment, supplies and materials and cinchona barks, under the provisions of Republic Acts Nos. 115 and 2706;\n76. The Board of Technical Surveys and Maps, for the execution of field pilot surveying and mapping projects, supplemental surveys and coordinating the functions of other agencies under Republic Act No. 2912;\n77. The Rice and Corn Board, for the enforcement and execution of the provisions of Republic Act No. 3018 regarding the nationalization of the rice and corn industry; and\n78. The Cooperatives Administration Office, for organizational and informational work on non-agricultural cooperatives."}},{"id":"PH-H2936-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Authority to pay representation allowance out of savings. —Heads of Departments and other members of the Cabinet, the Auditor General, the Secretary of the House of Representatives, and the Chairman and the two members of the Commission on Elections are hereby granted representation allowance at the rate of not exceeding two hundred fifty pesos each per month commutable monthly; and the Undersecretaries of Departments and officials with the same rank including the Legal Adviser to the President, the Legislative Secretary, the Chairman, Land Tenure Administration, the Judicial Superintendent and the Chief Prosecuting Attorney of the Department of Justice the Land Registration Commissioner, the Postmaster General, and the Deputy Commissioner of Civil Service, at the rate of not exceeding two hundred pesos each per month also commutable monthly: PROVIDED, That the said allowance shall be paid out of the savings in the appropriations provided for the respective departments and offices of the officials concerned."}},{"id":"PH-H2936-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Proper use of government motor vehicles. — The use of government motor vehicles by bureaus and offices for the purposes enumerated in section fourteen hereof shall be authorized only through the issuance for each trip of a serially numbered ticket, duly signed by the chief or the administrative officer of the bureau or office concerned. These motor vehicles shall be used strictly for official business, bear government plates only and after office hours kept in the garage provided therefor by the bureau or office to which they belong, except when in use for strictly official business outside office hours. Any violation of the provisions of this section shall cause withdrawal of the privilege to use motor vehicles from the office or bureau concerned."}},{"id":"PH-H2936-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Use of more than one motor vehicle prohibited. —With the exception of the President, no government official or employee authorized to use any vehicle operated and maintained from the funds appropriated in this Act shall be allowed to use more than one such motor vehicle: PROVIDED, HOWEVER, That the Vice-President, the President of the Senate and the Speaker of the House of Representatives may be allowed to use two motor vehicles each: PROVIDED FURTHER, That no official who has been furnished motor transportation allowance by any government corporation or any other official shall be allowed to use motor vehicle transportation operated and maintained from funds appropriated in this Act. The Auditor General is hereby empowered to issue rules and regulations for the proper implementation and enforcement of the provisions of this section and sections 13, 14 and 16."}},{"id":"PH-H2936-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Disposition of motor vehicles not used by a bureau or office. —All motor vehicles owned by or assigned to the different departments, bureaus, offices and branches of the National Government not needed by the officials and for the purposes enumerated in sections twelve and fourteen of this Act shall be disposed of in accordance with the rules and regulations prescribed by the General Auditing Office, to the highest bidder at public auction sales announced in newspaper of general circulation at least ten days before the sale: PROVIDED, That the former user thereof shall be given preference if he offers and pays a price equal to that of the highest bid by others."}},{"id":"PH-H2936-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Prohibition against the use of appropriation for the payment of salaries and wages of officers or employees engaged in strike against the Government. — Subject to existing civil service rules and regulations and the proper administrative proceedings, no part of the funds of, or available for expenditures by any agency included in this Act shall be used to pay the salary or wages of any officer or employee who engages in a strike against the Government of the Republic of the, Philippines or who is a member of an organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or who advocates, or is a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence: PROVIDED, That for the purposes hereof an affidavit shall be considered sufficient evidence that the person making the affidavit has not, contrary to the provisions of this section, engaged in a strike against the Government of the Republic of the Philippines, is not a member of any organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or that such person does not advocate, and is not a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence."}},{"id":"PH-H2936-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Per diems outside of the Philippines. —No per diems in excess of the equivalent of twenty-five dollars in pesos at the prevailing rate of exchange, shall be paid to any official or employee traveling outside of the Philippines."}},{"id":"PH-H2936-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"No transfer of salary savings to the Government Service Insurance System. —The provisions of Republic Act No. 660, as amended, to the contrary notwithstanding, no savings from personal services under the general fund and the special, revolving, trust, depository and other funds shall be transferred to the Government Service Insurance System."}},{"id":"PH-H2936-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Reinsurance of government buildings to be equitably distributed among private insurance companies in the Philippines. —In all cases where appropriations are provided in this Act for payment of premiums covering the insurance of government buildings with the Property Insurance Fund, reinsurance shall be equitably distributed among private insurance companies doing business in the Philippines at least sixty per cent of the capital stock of which are owned by citizens of the Philippines on uniform terms, conditions and rates of premiums."}},{"id":"PH-H2936-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Authority to harmonize the appropriation structure with new terminology of classification of accounts. —The Commissioner of the Budget is hereby authorized to harmonize the appropriation structure with the new terminology of classification of accounts that may be prescribed by law or regulations: PROVIDED, That such re-classification shall not increase or decrease the aggregate sum appropriated in this Act for the various objects affected under each department, bureau, or office: PROVIDED, FURTHER, That the Commissioner of the Budget shall submit to the Congress before the beginning of each session a report of such action."}},{"id":"PH-H2936-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives authorized to look into all matters relating to public expenditures. —The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives are hereby authorized to look at any time into all matters relating to funds for the expenditures of the National Government and for the payment of public indebtedness; auditing of accounts and expenditures of the National Government, including government-owned or controlled Corporations; claims against the Government; and in general all matters relating to public expenditures. The authority herein granted shall be without prejudice to the right of any member of the Congress to request the Committee on Finance of the Senate or the Committee on Appropriations of the House of Representatives as the case may be to look at any time into the matters referred to in this section either as member of the aforementioned Committees or as a member of the Congress."}},{"id":"PH-H2936-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Expenditure and disbursement of special funds. —Except as otherwise provided in this Act no portion of any unallotted balance of special, revolving, and trust funds and receipts automatically appropriated shall be available for expenditure: PROVIDED, That no expenditure shall be incurred, nor any disbursement made, out of the appropriations authorized in this Act under said funds and receipts automatically appropriated which will exceed at any one time either the fund itself or the cash in the National Treasury pertaining to such fund, except when, in the opinion of the President, such expenditure or disbursement is required by the exigency of the service, and sufficient income or receipts are expected to accrue to such funds to cover said expenditure or disbursement in which case the necessary amount may be advanced from the general fund."}},{"id":"PH-H2936-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Appropriations chargeable against the Philippine Charity Sweepstakes Fund. —The appropriations provided in this Act for carrying out the activities heretofore financed from the receipts of the Philippine Charity Sweepstakes Fund shall continue to be charged against the said Fund, and the Board of Directors of the Philippine Charity Sweepstakes shall allot the amount thereof in the distribution of the Philippine Charity Sweepstakes Fund."}},{"id":"PH-H2936-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Immediate payment of accounts. —In order to insure the immediate collection ox income due any bureau or office for services rendered or sale of any commodity or article produced or manufactured by the same, no such service shall be rendered or sale made except on the cash basis. Any official or employee who allows such service to be rendered or sale to be made on account shall be held personally liable therefor and such act shall be considered sufficient ground for his removal from office. The provisions of this section shall apply not only to transactions of the government with private parties but also with government-owned or controlled corporations, and officials and employees of the Government: PROVIDED, That sales on credit may be made to government officials and employees holding regular positions upon a down payment of twenty-five per centum of the value of the commodity or the service and upon certification of the head of the agency of the debtor that such amount as may be necessary to liquidate the balance shall be deducted regularly from the debtor's salary during a period not exceeding one year from the date the sale is made. The remittances to the creditor agency shall be made within fifteen days from the date the deductions are made."}},{"id":"PH-H2936-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Reversion of unliquidated balances of accounts payable. —Any provision of law to the contrary notwithstanding, the Auditor General, upon notice to the head of the office or agency concerned, shall revert to the unappropriated surplus of the general fund of the National Government, all unliquidated balances of accounts payable in the books of the National Government which are outstanding for one year or more upon the effectivity of this Act, unless they are the subject of pending claims and/or court litigations or covered by duly perfected contracts: PROVIDED, That in the case of Foreign Legations only those which are outstanding for two years or more shall be reverted: AND PROVIDED, FURTHER, That the provisions of this section shall not apply to unliquidated balances of accounts payable in trust funds so long as the purposes for which such funds have been created have not been accomplished."}},{"id":"PH-H2936-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Remittance of premiums for life and retirement insurance with the Government Service Insurance System. —The provisions of Republic Act Numbered Six hundred sixty, as amended, to the contrary notwithstanding, the premiums for life and retirement insurance of the employees of the National Government and its instrumentalities shall be remitted monthly to the Government Service Insurance System as they are due and collected."}},{"id":"PH-H2936-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Maximum Number of Permanent Positions in a Bureau or Office. —Except as otherwise provided by law the maximum number of permanent positions in a bureau or office shall not exceed the number of permanent positions included in the schedules for the said bureau or office in the budget document."}},{"id":"PH-H2936-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Adjustment of Appropriations for Reorganized Agencies and Salaries of Personnel Thereof. —The appropriations herein provided for agencies to be reorganized in accordance with the approved reorganization plans are deemed appropriated for the agencies as reorganized in case the Reorganization Implementation Reports are approved and promulgated by the President. The Commissioner of the Budget is hereby authorized to make necessary adjustments in the appropriations to carry out the personnel to fill the positions in the staffing patterns of foregoing provisions of this section. Furthermore, the department head concerned, with the approval of the. Commissioner of the Budget is hereby authorized to make necessary salary adjustments resulting from final selection of personnel to fill the positions in the staffing patterns of reorganized agencies in order that no incumbent receives a reduction in salary, to make necessary salary adjustments resulting from new appointments, promotions or salary increases made in the interim, and make necessary salary adjustments resulting from changes in the staffing patterns authorized by the Commissioner of the Budget to correct mistakes, discriminations or injustices that may, in his opinion, have been committed in the preparation thereof: PROVIDED, That any such adjustments in the staffing patterns of reorganized agencies which have been or may be authorized but not yet reflected in this Act shall be given due course by adjusting the corresponding appropriations herein authorized.\nNo provision of this Act shall be construed as repealing or modifying in any way the approved reorganization plans under Republic Act No. 997, as amended."}},{"id":"PH-H2936-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Change of designation of any position by WAPCO classification. —The change of designation of any position authorized in this Act due to the classification of such position in accordance with the WAPCO Plan shall not affect the tenure of office of the incumbent, shall not constitute a demotion either in rank or salary nor result in a change of status or assignment and the incumbent shall in all cases be deemed to have been appointed in that position and class: PROVIDED, HOWEVER, That any change in designation effected in this Act shall not affect in any manner the status or tenure of office of the incumbent, the provisions of any existing law to the contrary notwithstanding."}},{"id":"PH-H2936-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Adjustments of salaries and wages of employees and laborers paid from lump-sum appropriations. —Employees and laborers paid from lump-sum appropriations provided for in this Act shall be paid from the same appropriations their salary and wage adjustments for the implementation of the pay plan provided in Reorganization Plan No. 2-A: PROVIDED, That any provision of law to the contrary notwithstanding, employees and laborers whose authorized salaries are two thousand three hundred four pesos and below per annum or whose wages are equivalent to two thousand three hundred four pesos and below per annum shall each be paid out of the same appropriations additional salary or wage adjustment in such amounts as will make the total of this additional salary or wage adjustment and the salary or wage adjustment provided to implement Reorganization Plan No. 2-A equal to one hundred twenty pesos per annum each: AND PROVIDED, FURTHER, That positions of temporary and emergency employees and laborers which are provided from lump-sum appropriations with a monthly compensation of two hundred pesos a month or below or with a daily wage of nine pesos or below shall be given an increase of ten pesos a month each if the compensation is on the monthly basis and forty-five centavos a day each if on the daily basis."}},{"id":"PH-H2936-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Effective date. —This Act shall take effect on July first, nineteen hundred and sixty-two, except where otherwise provided.\nApproved, June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2937"] = {"id":"PH-H2937","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3501_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Ilang Primary School in the District of Tibungco, Davao City, to Sixto Babao Primary School","orig":"An Act Changing the Name of Ilang Primary School in the District of Tibungco, Davao City, to Sixto Babao Primary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3501","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3501_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2937-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Ilang Primary School in the District of Tibungco, Davao City, is changed to Sixto Babao Primary School."}},{"id":"PH-H2937-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2938"] = {"id":"PH-H2938","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3502_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Albay Normal School to Bicol Teachers College","orig":"An Act Changing the Name of Albay Normal School to Bicol Teachers College"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3502","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3502_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2938-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Albay Normal School is hereby changed to Bicol Teachers College."}},{"id":"PH-H2938-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2939"] = {"id":"PH-H2939","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3503_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tuburan National Vocational School in the Municipality of Tuburan, Province of Cebu, to Tuburan National School","orig":"An Act Changing the Name of the Tuburan National Vocational School in the Municipality of Tuburan, Province of Cebu, to Tuburan National School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3503","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3503_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2939-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tuburan National Vocational School in the Municipality of Tuburan, Province of Cebu, is hereby changed to Tuburan National School. General courses as well as vocational courses shall be offered in said school."}},{"id":"PH-H2939-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2940"] = {"id":"PH-H2940","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3504_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Milibili Barrio School in Roxas City to Don Manuel Arnaldo Memorial School","orig":"An Act Changing the Name of the Milibili Barrio School in Roxas City to Don Manuel Arnaldo Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3504","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3504_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2940-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Milibili Barrio School in Roxas City is hereby changed to Don Manuel Arnaldo Memorial School."}},{"id":"PH-H2940-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2941"] = {"id":"PH-H2941","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3505_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Tinio-an Elementary School in the Municipality of Cabanatuan, Province of Iloilo, to Doroteo Lujan Elementary School","orig":"An Act Changing the Name of the Tinio-an Elementary School in the Municipality of Cabanatuan, Province of Iloilo, to Doroteo Lujan Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3505","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3505_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2941-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Tinio-an Elementary School in the Municipality of Cabanatuan, Province of Iloilo, is changed to Doroteo Lujan Elementary School."}},{"id":"PH-H2941-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
  FT["PH-H2942"] = {"id":"PH-H2942","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1962/ra_3506_1962.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the La Loma Elementary School in Quezon City to Magsaysay Elementary School","orig":"An Act Changing the Name of the La Loma Elementary School in Quezon City to Magsaysay Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3506","issuingBody":"Congress of the Philippines","promulgatedDate":"1962-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1962/ra_3506_1962.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2942-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the La Loma Elementary School in Quezon City is changed to Magsaysay Elementary School."}},{"id":"PH-H2942-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1962."}}],"pack":"ph-p41"};
